-- Seed generated from the production CSV exports (Wisdom Database replica).
-- Works with the inferred schema in supabase/migrations or with the real pulled schema:
-- rows are staged as text, then cast to whatever type each target column actually has.
set session_replication_role = replica;  -- skip FK checks and triggers while loading
drop schema if exists _seed cascade;
create schema _seed;

-- realms: 4 rows
create table _seed.realms ("key" text, "name" text, "description" text, "is_live" text, "sort_order" text, "config" text, "created_at" text);

-- faculties: 29 rows
create table _seed.faculties ("id" text, "name" text, "is_special" text, "realm_key" text);

-- academic_sessions: 4 rows
create table _seed.academic_sessions ("id" text, "name" text, "is_current" text, "realm_key" text);

-- semesters: 3 rows
create table _seed.semesters ("id" text, "name" text, "is_current" text, "session_id" text);

-- departments: 138 rows
create table _seed.departments ("id" text, "name" text, "faculty_id" text);

-- hall_groups: 52 rows
create table _seed.hall_groups ("id" text, "created_at" text);

-- rooms: 503 rows
create table _seed.rooms ("id" text, "name" text, "capacity" text, "faculty_id" text, "display_order" text, "is_lab" text, "is_active" text, "active_seats" text, "inactive_seats" text, "realm_key" text, "hall_group_id" text);

-- courses: 8903 rows
create table _seed.courses ("id" text, "code" text, "title" text, "credit_load" text, "lecturers" text, "department_id" text, "scope" text, "level" text, "semester" text, "is_cbt_exam" text, "realm_key" text);

-- schedule_items: 6161 rows
create table _seed.schedule_items ("id" text, "course_id" text, "room_ids" text, "faculty_id" text, "day_of_week" text, "start_time" text, "end_time" text, "type" text, "week" text, "exam_date" text, "semester_id" text, "is_online" text, "realm_key" text);

-- course_enrollments: 91 rows
create table _seed.course_enrollments ("id" text, "course_id" text, "department_id" text, "level" text, "enrolled_by" text, "enrolled_at" text);

-- blocked_slots: 7 rows
create table _seed.blocked_slots ("id" text, "name" text, "type" text, "date" text, "day_of_week" text, "start_time" text, "end_time" text, "applies_to" text, "semester_id" text);

-- conflict_dismissals: 503 rows
create table _seed.conflict_dismissals ("id" text, "conflict_type" text, "item_a_id" text, "item_b_id" text, "reason" text, "created_by" text, "created_at" text);

-- timetable_locks: 5 rows
create table _seed.timetable_locks ("id" text, "semester_id" text, "timetable_type" text, "is_locked" text, "locked_by" text, "locked_at" text);

do $$
declare
  t text; cols text; exprs text; seq text; existing text;
begin
  select string_agg(format('public.%I', x), ', ') into existing
  from unnest(array['realms','faculties','academic_sessions','semesters','departments','hall_groups','rooms','courses','schedule_items','course_enrollments','blocked_slots','conflict_dismissals','timetable_locks']) x where to_regclass('public.' || x) is not null;
  if existing is not null then execute 'truncate ' || existing || ' restart identity cascade'; end if;

  foreach t in array array['realms','faculties','academic_sessions','semesters','departments','hall_groups','rooms','courses','schedule_items','course_enrollments','blocked_slots','conflict_dismissals','timetable_locks'] loop
    if to_regclass('public.' || t) is null then
      raise notice 'skipping %: no such table in public', t; continue;
    end if;
    select string_agg(format('%I', c.column_name), ', ' order by c.ordinal_position),
           string_agg(
             case
               when c.data_type = 'ARRAY' then
                 format('nullif(translate(s.%I, ''[]'', ''{}''), '''')::%s', c.column_name, format_type(a.atttypid, a.atttypmod))
               when c.data_type in ('text','character varying','character') and c.is_nullable = 'NO' then
                 format('s.%I::%s', c.column_name, format_type(a.atttypid, a.atttypmod))
               else
                 format('nullif(s.%I, '''')::%s', c.column_name, format_type(a.atttypid, a.atttypmod))
             end, ', ' order by c.ordinal_position)
      into cols, exprs
    from information_schema.columns c
    join information_schema.columns sc
      on sc.table_schema = '_seed' and sc.table_name = t and sc.column_name = c.column_name
    join pg_attribute a
      on a.attrelid = format('public.%I', t)::regclass and a.attname = c.column_name
    where c.table_schema = 'public' and c.table_name = t and c.is_generated = 'NEVER';

    execute format('insert into public.%I (%s) overriding system value select %s from _seed.%I s', t, cols, exprs, t);

    -- move the id sequence past the imported ids so new inserts don't collide
    seq := null;
    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = t
               and column_name = 'id' and data_type in ('integer','bigint','smallint')) then
      seq := pg_get_serial_sequence(format('public.%I', t), 'id');
    end if;
    if seq is not null then
      execute format('select setval(%L, greatest((select coalesce(max(id), 0) from public.%I), 1))', seq, t);
    end if;
    raise notice 'loaded %', t;
  end loop;
end $$;

drop schema _seed cascade;
set session_replication_role = default;
